import sys

# Increase recursion depth just in case
sys.setrecursionlimit(200005)

def solve():
    # Read all input from stdin
    # Using sys.stdin.read().split() handles all whitespace (spaces, newlines) automatically
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Union-Find data structure
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(i):
        # Iterative path compression
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            # Union by rank
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_i] = root_j
                rank[root_j] += 1
            return True
        return False

    merges_count = 0

    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
        except StopIteration:
            break
        if union(u, v):
            merges_count += 1

    # The number of edges to remove is M - merges_count
    print(M - merges_count)

if __name__ == '__main__':
    solve()

