class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows = len(grid)
        cols = len(grid[0])

        # Iterate through each row
        for r in range(rows):
            # Determine the pattern based on the row index
            # Based on the examples:
            # - Even rows (0, 2, 4...) traverse right and collect cells at even indices (0, 2, 4...)
            # - Odd rows (1, 3, 5...) traverse left and collect cells at odd indices (1, 3, 5...)
            if r % 2 == 0:
                # Even row: Traverse right, visit even indices
                for c in range(0, cols, 2):
                    result.append(grid[r][c])
            else:
                # Odd row: Traverse left, visit odd indices
                for c in range(1, cols, 2):
                    result.append(grid[r][c])

        return result

