class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counts = {}
        n = len(nums)

        # Iterate through all subarrays of size k
        for i in range(n - k + 1):
            # Get the subarray elements
            subarray = nums[i : i + k]
            # Use a set to ensure each element in the subarray is counted once for this subarray
            unique_elements = set(subarray)
            # Update the count for each unique element found in this subarray
            for num in unique_elements:
                counts[num] = counts.get(num, 0) + 1

        # Identify numbers that appear in exactly one subarray
        almost_missing = [num for num, count in counts.items() if count == 1]

        # Return the largest such number, or -1 if none exist
        if not almost_missing:
            return -1
        return max(almost_missing)

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Track which baskets are used
        used = [False] * n

        # For each fruit, find the leftmost available basket with capacity >= fruit quantity
        for i in range(n):
            fruit_qty = fruits[i]
            placed = False
            for j in range(n):
                if not used[j] and baskets[j] >= fruit_qty:
                    used[j] = True
                    placed = True
                    break

            if not placed:
                return 1  # This fruit type cannot be placed

        return 0

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Calculate the maximum number of containers allowed by the ship's weight capacity.
        # This is the integer division of the maxWeight by the weight of a single container w.
        max_containers_by_weight = maxWeight // w

        # Calculate the total number of cells available on the n x n deck.
        max_containers_by_deck = n * n

        # The actual number of containers we can load is limited by both the ship's capacity
        # and the physical space available on the deck.
        return min(max_containers_by_weight, max_containers_by_deck)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Initialize Union-Find structure
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                return True
            return False

        # Build the graph by checking all pairs
        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both arrays
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    union(i, j)

        # Count connected components by counting unique roots
        root_count = 0
        for i in range(n):
            if parent[i] == i:
                root_count += 1

        return root_count

