class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        for i in range(n):
            # Calculate absolute difference between current element and next element
            # Use modulo operator to handle circular adjacency (last element adjacent to first)
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        from collections import Counter

        # Count frequency of each digit
        count = Counter(s)

        # Iterate through adjacent pairs
        for i in range(len(s) - 1):
            first_digit = s[i]
            second_digit = s[i+1]

            # Check if they're not equal
            if first_digit == second_digit:
                continue

            # Check if each digit appears as many times as its numeric value
            if count[first_digit] == int(first_digit) and count[second_digit] == int(second_digit):
                return first_digit + second_digit

        return ""

