class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)
        for i in range(n):
            is_good = True
            # Check if nums[i] is strictly greater than nums[i - k]
            if i - k >= 0 and nums[i] <= nums[i - k]:
                is_good = False
            # Check if nums[i] is strictly greater than nums[i + k]
            if i + k < n and nums[i] <= nums[i + k]:
                is_good = False

            if is_good:
                total_sum += nums[i]
        return total_sum
